CREATE TABLE published_equipment_counts(unit_id TEXT NOT NULL,category TEXT NOT NULL,records INTEGER NOT NULL DEFAULT 0,items INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(unit_id,category));
INSERT INTO published_equipment_counts(unit_id,category,records,items) SELECT unit_id,json_extract(published_json,'$.category'),COUNT(*),SUM(CAST(COALESCE(json_extract(published_json,'$.quantity'),1) AS INTEGER)) FROM equipments WHERE published_json IS NOT NULL GROUP BY unit_id,json_extract(published_json,'$.category');
CREATE TRIGGER published_equipment_update AFTER UPDATE OF published_json ON equipments WHEN NEW.published_json IS NOT OLD.published_json BEGIN
 UPDATE published_equipment_counts SET records=records-1,items=items-CAST(COALESCE(json_extract(OLD.published_json,'$.quantity'),1) AS INTEGER) WHERE unit_id=OLD.unit_id AND category=json_extract(OLD.published_json,'$.category') AND OLD.published_json IS NOT NULL;
 INSERT INTO published_equipment_counts(unit_id,category,records,items) SELECT NEW.unit_id,json_extract(NEW.published_json,'$.category'),1,CAST(COALESCE(json_extract(NEW.published_json,'$.quantity'),1) AS INTEGER) WHERE NEW.published_json IS NOT NULL ON CONFLICT(unit_id,category) DO UPDATE SET records=records+1,items=items+excluded.items;
END;
CREATE TABLE published_unit_status(unit_id TEXT PRIMARY KEY,visits INTEGER NOT NULL DEFAULT 0,latest INTEGER,environment_count INTEGER NOT NULL DEFAULT 0);
INSERT INTO published_unit_status(unit_id,visits,latest,environment_count) SELECT unit_id,COUNT(*),MAX(completed_at),(SELECT COUNT(*) FROM inspection_environments WHERE inspection_id=(SELECT latest_i.id FROM inspections latest_i WHERE latest_i.unit_id=inspections.unit_id AND latest_i.state='completed' ORDER BY completed_at DESC,id DESC LIMIT 1)) FROM inspections WHERE state='completed' GROUP BY unit_id;
